-- The four commentaries set side by side, per passage (owner, 2026-10-16): what they share (common), where they part
-- (contrast: each book's position), what each dwells on (focus), and where a book's theological school shows (theology).
-- Read from every prepared sentence of the four works (qr_tafsir_sentence), each item citing the sentences it rests on;
-- a school shown only where the text supports it (40:1–3: al-Zamakhsharī and Ibn ʿĀshūr take no school position).
CREATE TABLE IF NOT EXISTS qr_tafsir_contrast (
  id          TEXT PRIMARY KEY,
  passage_id  TEXT NOT NULL,
  ord         INTEGER NOT NULL,
  kind        TEXT NOT NULL CHECK (kind IN ('common','contrast','focus','theology')),
  ayah        TEXT,
  topic_en    TEXT NOT NULL,
  topic_ar    TEXT,
  point_en    TEXT NOT NULL,
  books_json  TEXT NOT NULL,
  positions_json TEXT,
  sentences_json TEXT NOT NULL,
  drill_json  TEXT,
  status      TEXT NOT NULL DEFAULT 'live',
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_qr_tafsir_contrast_passage ON qr_tafsir_contrast(passage_id, ord);
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:01', 'QR:SP:40:1-3', 1, 'common', '40:1', 'How حم is read', 'قراءات حم', 'Three of four (not Ibn ʿĀshūr) list the readings of حم: the ا of حا said full or with إمالة, and م silent or with a فتحة. The فتحة is explained either by two silent letters meeting (التقاء الساكنين), with فتحة as the lightest vowel, or by a hidden verb اقرأ making حم accusative; it then takes no full endings (منع الصرف) as a feminine/definite or foreign-looking name.', '["zamakhshari", "razi", "alusi"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:4-4", "tafsir_sent:QRTA:zamakhshari:40-01:5-6", "tafsir_sent:QRTA:razi:40-01:9-10", "tafsir_sent:QRTA:razi:40-01:11-12", "tafsir_sent:QRTA:razi:40-01:13-13", "tafsir_sent:QRTA:alusi:40-01:47-49", "tafsir_sent:QRTA:alusi:40-01:50-52"]', '{"prompt": "Some readers say «حَمَ» with a فتحة on the م. Which reason is given for that فتحة?", "options": ["Two silent letters meet, and فتحة is the lightest vowel to break them", "حم is the subject (مبتدأ), so it must take a فتحة", "The م is followed by a هاء that needs a فتحة before it", "It is الإمالة: the ا leans toward i, so the م leans toward a"], "answer": "Two silent letters meet, and فتحة is the lightest vowel to break them", "explanation": "al-Zamakhsharī, al-Rāzī and al-Ālūsī all give التقاء الساكنين (as in أين، كيف) or a hidden «اقرأ»; a subject would take ضمة, not فتحة, and إمالة concerns the ا, not the م."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:02', 'QR:SP:40:1-3', 2, 'common', '40:3', '«غافر الذنب» and «قابل التوب» name lasting qualities', 'غافر الذنب وقابل التوب صفتان ثابتتان', 'All four say غافر and قابل here do not mean ''He forgives now or tomorrow'' but qualities God always has. So their annexation is pure (إضافة معنوية) and makes them definite, which lets them describe the definite name الله, like «إله الخلق» and «رب العرش».', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:12-14", "tafsir_sent:QRTA:zamakhshari:40-01:23-24", "tafsir_sent:QRTA:razi:40-01:81-84", "tafsir_sent:QRTA:alusi:40-01:82-83", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:32-34"]', '{"prompt": "Why can «غافرِ الذنب» describe the definite name الله in 40:3?", "options": ["It names a lasting quality, so its annexation is pure and makes it definite", "It names an act happening now, so it works like a verb", "It is a substitute (بدل), so it need not match in definiteness", "It carries a hidden ال that was dropped for the rhyme"], "answer": "It names a lasting quality, so its annexation is pure and makes it definite", "explanation": "All four works agree: an active participle that means a fixed quality (not a timed act) gets a real, definite-making annexation (إضافة معنوية)."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:03', 'QR:SP:40:1-3', 3, 'common', '40:3', 'The problem of «شديد العقاب»', 'إشكال شديد العقاب', 'All four see a problem: شديد is an adjective like a participle (صفة مشبهة) that really means ''whose punishment is severe'' (شديدٌ عقابُه). Its annexation looks only surface-level (إضافة لفظية), so it seems indefinite, yet it describes the definite الله.', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:11-11", "tafsir_sent:QRTA:zamakhshari:40-01:15-16", "tafsir_sent:QRTA:zamakhshari:40-01:25-26", "tafsir_sent:QRTA:razi:40-01:75-77", "tafsir_sent:QRTA:razi:40-01:78-80", "tafsir_sent:QRTA:razi:40-01:85-86", "tafsir_sent:QRTA:alusi:40-01:84-86", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:35-36", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:37-39"]', '{"prompt": "What makes «شديد العقاب» hard to read as a describing word (نعت) of الله?", "options": ["Its annexation is only surface-level, so it looks indefinite beside a definite noun", "It is a verb, and a verb cannot describe a noun", "It is feminine while الله is masculine", "It is plural while the other names are singular"], "answer": "Its annexation is only surface-level, so it looks indefinite beside a definite noun", "explanation": "شديد is a صفة مشبهة meaning ''whose punishment is severe''; its link to العقاب (إضافة لفظية) does not obviously make it definite, so it seems to clash with الله."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:04', 'QR:SP:40:1-3', 4, 'common', '40:3', 'The و joins two mercies for the one who repents', 'الواو تجمع للتائب رحمتين', 'Three of four (not al-Rāzī) say the و in «وقابل التوب» shows the repentant sinner gets two mercies at once: God accepts his repentance and counts it as obedience, and makes it wipe out the sin as if it never happened — ''the One who joins forgiveness and acceptance''.', '["zamakhshari", "alusi", "ibn_ashur"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:45-45", "tafsir_sent:QRTA:zamakhshari:40-01:46-49", "tafsir_sent:QRTA:alusi:40-01:114-116", "tafsir_sent:QRTA:alusi:40-01:117-119", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:26-29"]', '{"prompt": "In «غافرِ الذنبِ وقابلِ التوبِ», what does the و add, on the ''two mercies'' reading?", "options": ["The one who repents gets both: repentance accepted as obedience, and the sin wiped out", "Forgiveness is for those who did not repent, acceptance for those who did", "Forgiveness is in this world, acceptance in the next", "It only keeps the rhythm of the verse and adds no meaning"], "answer": "The one who repents gets both: repentance accepted as obedience, and the sin wiped out", "explanation": "al-Zamakhsharī, al-Ālūsī and Ibn ʿĀshūr read the و as joining two mercies for one person; al-Ālūsī rejects the ''two groups'' split, and none treats the و as filler."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:05', 'QR:SP:40:1-3', 5, 'common', '40:3', 'What «التوب» is', 'معنى التوب', 'All four explain التوب. al-Zamakhsharī and Ibn ʿĀshūr say التوب, الثوب and الأوب are ''sisters'' meaning returning; al-Rāzī, al-Ālūsī and Ibn ʿĀshūr take it as a verbal noun (مصدر) of تاب, with al-Rāzī and al-Ālūsī also allowing a plural/collective of توبة (like تمر / تمرة).', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:7-8", "tafsir_sent:QRTA:razi:40-01:66-67", "tafsir_sent:QRTA:razi:40-01:68-70", "tafsir_sent:QRTA:alusi:40-01:110-111", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:25-25"]', '{"prompt": "«التوب» in «قابل التوب» shares its core meaning with الثوب and الأوب. What is that meaning?", "options": ["Returning", "Covering", "Regret", "Purifying"], "answer": "Returning", "explanation": "al-Zamakhsharī and Ibn ʿĀshūr: all three words mean coming back — here, coming back to God''s command. ''Covering'' is the root sense of غفر, not توب."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:06', 'QR:SP:40:1-3', 6, 'common', '40:3', '«ذي الطول» means bounty and favour', 'ذو الطول: ذو الفضل', 'All four take الطول as favour or bounty, not length: Arabs say «طال عليه» or «تطوّل» for doing someone a favour. Al-Rāzī cites «أولو الطول» and «طولا» in other sūras; Ibn ʿĀshūr and al-Ālūsī also note the sense of power.', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:7-8", "tafsir_sent:QRTA:zamakhshari:40-01:9-10", "tafsir_sent:QRTA:razi:40-01:113-116", "tafsir_sent:QRTA:razi:40-01:117-119", "tafsir_sent:QRTA:alusi:40-01:112-113", "tafsir_sent:QRTA:alusi:40-01:114-116", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:40-44"]', '{"prompt": "What does «الطول» mean in «ذي الطول» (40:3)?", "options": ["Bounty and favour", "Length and height", "Patience and long delay", "Long-lasting time"], "answer": "Bounty and favour", "explanation": "All four: «طال عليه / تطوّل» means ''he did him a favour''. ''Length'' is the everyday sense, and ''delay'' is a near miss that none of them give."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:07', 'QR:SP:40:1-3', 7, 'common', '40:3', 'The names stir hope and fear', 'الترغيب والترهيب', 'All four read the names of 40:3 as working on hope and fear together: forgiveness, acceptance and bounty give hope (ترغيب), «شديد العقاب» gives fear (ترهيب). al-Zamakhsharī and al-Ālūsī show it through the man in ʿUmar''s letter who said ''God promised to forgive me and warned me of His punishment''.', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:58-60", "tafsir_sent:QRTA:razi:40-01:40-41", "tafsir_sent:QRTA:razi:40-01:127-130", "tafsir_sent:QRTA:alusi:40-01:79-81", "tafsir_sent:QRTA:alusi:40-01:139-140", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:23-24", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:46-48"]', '{"prompt": "Of the names in 40:3 — غافر الذنب، قابل التوب، شديد العقاب، ذي الطول — which one stirs fear (ترهيب) rather than hope?", "options": ["شديد العقاب", "ذي الطول", "قابل التوب", "غافر الذنب"], "answer": "شديد العقاب", "explanation": "al-Ālūsī: three names give hope and one gives fear; al-Rāzī and Ibn ʿĀshūr also pair ترغيب with ترهيب. (Ibn ʿĀshūr adds a warning sense to ذي الطول as power, but the plain fear-name is شديد العقاب.)"}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:08', 'QR:SP:40:1-3', 8, 'contrast', '40:3', 'Why there is a و only before «قابل التوب»', 'سرّ الواو في وقابل التوب', 'All four ask why only this pair is joined with و. Three see ''two mercies for one person''; al-Rāzī instead says the و shows the two names are two different traits.', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{"zamakhshari": "The و joins two mercies for the repentant: repentance accepted and sin wiped out.", "razi": "Without و one might think the two names mean the same; و marks them as two traits. No و before شديد العقاب because that one is plainly different.", "alusi": "Two mercies for the repentant; eloquent speech has no wasted و. He rejects ''two groups'' and says other differences come from the names, not the و.", "ibn_ashur": "Most names follow without و (فصل); joining just this pair (عطف) points to two mercies together for the repentant."}', '["tafsir_sent:QRTA:zamakhshari:40-01:46-49", "tafsir_sent:QRTA:razi:40-01:104-107", "tafsir_sent:QRTA:razi:40-01:108-110", "tafsir_sent:QRTA:razi:40-01:111-112", "tafsir_sent:QRTA:alusi:40-01:117-119", "tafsir_sent:QRTA:alusi:40-01:120-121", "tafsir_sent:QRTA:alusi:40-01:122-123", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:26-29"]', '{"prompt": "One reading says: ''Without the و, a hearer might think «غافر الذنب» just means «قابل التوب»; the و shows they are two traits.'' What does this reading say about why no و comes before «شديد العقاب»?", "options": ["Severity is plainly different from forgiving, so no و is needed to mark it", "A و there would turn a threat into a promise", "«شديد العقاب» is a substitute, and substitutes never take و", "The rhyme of the verse would break with a و"], "answer": "Severity is plainly different from forgiving, so no و is needed to mark it", "explanation": "This is al-Rāzī''s answer: nothing is joined to itself, so و marks difference — needed only where the difference could be missed."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:09', 'QR:SP:40:1-3', 9, 'contrast', '40:3', 'Solving «شديد العقاب»', 'توجيه شديد العقاب', 'All four see the definiteness problem but solve it differently.', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{"zamakhshari": "Best: one indefinite among definites shows the whole chain is substitutes (أبدال), like one متفاعلن foot making a poem الكامل; or ال dropped to pair with its neighbours (ازدواج); or left indefinite on purpose to stress severity.", "razi": "Three answers: an indefinite sits well among definites (as in سورة البروج); or it is a substitute (بدل); or, like the others, it means a lasting trait.", "alusi": "Rejects every substitute reading. The Kufan school lets this adjective become definite; or شديد = مشدد (active participle); or ال dropped to match (مشاكلة).", "ibn_ashur": "Simply a describing word (نعت): the ال on العقاب gives the definiteness; the grammarians'' dispute is a small matter."}', '["tafsir_sent:QRTA:zamakhshari:40-01:17-17", "tafsir_sent:QRTA:zamakhshari:40-01:18-21", "tafsir_sent:QRTA:zamakhshari:40-01:36-38", "tafsir_sent:QRTA:zamakhshari:40-01:42-42", "tafsir_sent:QRTA:razi:40-01:87-90", "tafsir_sent:QRTA:razi:40-01:91-93", "tafsir_sent:QRTA:razi:40-01:94-96", "tafsir_sent:QRTA:alusi:40-01:89-90", "tafsir_sent:QRTA:alusi:40-01:91-92", "tafsir_sent:QRTA:alusi:40-01:93-94", "tafsir_sent:QRTA:alusi:40-01:110-111", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:35-36", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:37-39"]', '{"prompt": "One reading says: in a poem whose feet are all مستفعلن, a single متفاعلن makes the whole poem الكامل. What does this picture argue about the names in 40:3?", "options": ["One indefinite among them shows they are all substitutes (أبدال), not describing words", "They are all describing words, and شديد lost its ال for the rhythm", "Only «شديد العقاب» is a substitute; the rest are describing words", "The verse has a poetic metre, so grammar rules relax"], "answer": "One indefinite among them shows they are all substitutes (أبدال), not describing words", "explanation": "al-Zamakhsharī''s analogy: one sure sign decides the label of the whole set. He rejects making شديد العقاب alone a substitute (al-Zajjāj''s view) as jarring."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:10', 'QR:SP:40:1-3', 10, 'contrast', '40:2', 'Why «العزيز العليم»', 'سرّ العزيز العليم', 'Three of four explain why these two names follow «تنزيل الكتاب» (al-Zamakhsharī is silent). They part on what the names do.', '["razi", "alusi", "ibn_ashur"]', '{"razi": "Majestic names make the listener serious; power and knowledge show His acts are wise, so the revelation is true; they also let Him send it unmatched and keep it safe.", "alusi": "The Qurʾān is matchless (إعجاز) and holds endless knowledge; «العليم» replaces «الحكيم» of al-Zumar just for variety (تفنن).", "ibn_ashur": "An indirect message (تعريض) to deniers: العزيز — you are overpowered; العليم — He knows what you hide; and He knows best whom to give His message. This is why it is العليم here."}', '["tafsir_sent:QRTA:razi:40-01:20-21", "tafsir_sent:QRTA:razi:40-01:33-34", "tafsir_sent:QRTA:razi:40-01:35-37", "tafsir_sent:QRTA:razi:40-01:38-39", "tafsir_sent:QRTA:razi:40-01:40-41", "tafsir_sent:QRTA:alusi:40-01:77-78", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:12-14", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:15-16", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:18-19"]', '{"prompt": "Sūrat al-Zumar opens «العزيز الحكيم»; 40:2 has «العزيز العليم». On the reading that the names carry a hidden message to deniers, what does «العليم» hint at?", "options": ["God knows what the deniers hide and will hold them to account", "God knows the future, so the Qurʾān''s prophecies will come true", "God taught the Prophet to read and write", "Knowledge is the first step in knowing God"], "answer": "God knows what the deniers hide and will hold them to account", "explanation": "Ibn ʿĀshūr reads it as تعريض at deniers; al-Ālūsī sees mere variety (تفنن); al-Rāzī ties it to the Qurʾān''s wise and unmatched form."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:11', 'QR:SP:40:1-3', 11, 'contrast', '40:3', 'Why «غافر» comes before «قابل»', 'تقديم غافر على قابل', 'Two books explain the order, and give different reasons.', '["alusi", "ibn_ashur"]', '{"alusi": "Clearing comes before adorning (التخلية قبل التحلية): first the sin is cleared, then the repentance accepted.", "ibn_ashur": "In fact forgiveness follows accepted repentance; غافر is put first to tell anyone ready to change, right away, that forgiveness is there."}', '["tafsir_sent:QRTA:alusi:40-01:125-125", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:23-24"]', '{"prompt": "One reading says: in reality forgiveness comes after repentance is accepted, yet «غافر الذنب» is placed first. Why, on that reading?", "options": ["To announce forgiveness quickly to anyone ready to change", "Because forgiveness is more important than repentance", "Because clearing away bad must come before adding good", "Because «غافر» is shorter and fits the rhythm"], "answer": "To announce forgiveness quickly to anyone ready to change", "explanation": "This is Ibn ʿĀshūr. ''Clearing before adorning'' (التخلية قبل التحلية) is al-Ālūsī''s different reason for the same order."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:12', 'QR:SP:40:1-3', 12, 'contrast', '40:3', 'What «ذي الطول» points to here', 'مرجع الطول في السياق', 'All four agree الطول is favour, but they part on what favour it means next to «شديد العقاب».', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{"zamakhshari": "Bounty: giving more than is due.", "razi": "Coming right after severe punishment, it means He leaves a punishment He has the right to give — so pardon of major sins is possible.", "alusi": "Reward and blessings, not only sparing punishment, even though it follows «شديد العقاب».", "ibn_ashur": "Power: with «شديد العقاب» it warns of two punishments — next life (شديد العقاب) and this world (ذي الطول)."}', '["tafsir_sent:QRTA:zamakhshari:40-01:7-8", "tafsir_sent:QRTA:razi:40-01:122-123", "tafsir_sent:QRTA:razi:40-01:124-126", "tafsir_sent:QRTA:alusi:40-01:112-113", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:40-44"]', '{"prompt": "One reading takes «ذي الطول» as God''s power and says it warns of punishment in this world. What, on that reading, does «شديد العقاب» then warn of?", "options": ["Punishment in the next life", "Punishment in this world too", "Loss of wealth", "Being cut off from guidance"], "answer": "Punishment in the next life", "explanation": "Ibn ʿĀshūr splits the two: شديد العقاب for the hereafter, ذي الطول (power) for this world. al-Rāzī instead reads الطول as leaving deserved punishment."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:13', 'QR:SP:40:1-3', 13, 'contrast', '40:1', 'What حم does and how it joins verse 2', 'موقع حم وصلته بالتنزيل', 'They differ on whether حم is part of the sentence with «تنزيل الكتاب».', '["zamakhshari", "razi", "alusi", "ibn_ashur"]', '{"zamakhshari": "Deals only with how حم is read and why the م may take فتحة (including as object of a hidden اقرأ).", "razi": "حم names the sūra and is the subject (مبتدأ); «تنزيل الكتاب» is its predicate (خبر): this sūra is the revealed Book.", "alusi": "Same grammar as the start of al-Zumar, plus the new option that تنزيل is the predicate of حم; a ضمة reading also makes حم subject or predicate.", "ibn_ashur": "Like the other opening letters (حروف مقطعة): it comes before mention of the Book and challenges deniers to match it."}', '["tafsir_sent:QRTA:zamakhshari:40-01:5-6", "tafsir_sent:QRTA:razi:40-01:15-17", "tafsir_sent:QRTA:razi:40-01:18-18", "tafsir_sent:QRTA:alusi:40-01:75-76", "tafsir_sent:QRTA:alusi:40-01:54-55", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:1-2"]', '{"prompt": "On the reading that «حم» is the name of the sūra and the subject (مبتدأ), what is its predicate (خبر)?", "options": ["«تنزيل الكتاب من الله»", "«العزيز العليم»", "A hidden «اقرأ»", "«إليه المصير»"], "answer": "«تنزيل الكتاب من الله»", "explanation": "al-Rāzī (and al-Ālūsī as one option): ''this sūra, حم, is the sending down of the Book'' — with تنزيل meaning the thing sent down. A hidden اقرأ belongs to a different reading where حم is an object."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:14', 'QR:SP:40:1-3', 14, 'contrast', '40:3', '«لا إله إلا هو» and «إليه المصير»', 'لا إله إلا هو إليه المصير', 'Three of four explain the closing words (al-Zamakhsharī only quotes them in ʿUmar''s letter).', '["razi", "alusi", "ibn_ashur"]', '{"razi": "Fifth and sixth attributes: oneness means no one shares His mercy, so serving Him is needed; the return gives fear its full weight.", "alusi": "The clause may be a new sentence (مستأنفة), a حال, or a صفة; it calls for full obedience, and the return is to Him alone for repayment.", "ibn_ashur": "The clause stands as a صفة; together they record a clear verdict (تسجيل) against شرك and refute denial of resurrection; إليه is fronted for care and for the verse endings."}', '["tafsir_sent:QRTA:razi:40-01:127-130", "tafsir_sent:QRTA:razi:40-01:131-132", "tafsir_sent:QRTA:razi:40-01:133-135", "tafsir_sent:QRTA:alusi:40-01:129-130", "tafsir_sent:QRTA:alusi:40-01:131-132", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:45-45", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:46-48", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:49-51"]', '{"prompt": "In «إليه المصير», «إليه» comes before «المصير». Which pair of reasons is given for this?", "options": ["Care for it (اهتمام) and keeping the verse endings (رعاية الفاصلة)", "To make المصير indefinite and to stress the threat", "Because المصير is a verb and must come last", "Because إلى marks an end-point in space"], "answer": "Care for it (اهتمام) and keeping the verse endings (رعاية الفاصلة)", "explanation": "Ibn ʿĀshūr: the endings share a soft letter then a sound letter (العليم، البلاد، عقاب). The ''end-point in space'' idea is what al-Rāzī says the أهل التشبيه used."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:15', 'QR:SP:40:1-3', 15, 'focus', '40:3', 'Proof from prosody and Arab sayings', 'الاستشهاد بالعروض وكلام العرب', 'al-Zamakhsharī settles grammar with outside patterns: a poem''s metre (one متفاعلن makes it الكامل), the saying «ما يعرف سحادليه من عنادليه» for bending rules to pair words (ازدواج), and al-Khalīl''s examples of an ال held in mind.', '["zamakhshari"]', '{}', '["tafsir_sent:QRTA:zamakhshari:40-01:18-21", "tafsir_sent:QRTA:zamakhshari:40-01:33-35", "tafsir_sent:QRTA:zamakhshari:40-01:36-38", "tafsir_sent:QRTA:zamakhshari:40-01:39-41"]', '{"prompt": "Arabs said «ما يعرف سحادليه من عنادليه», putting a single thing in the dual to pair with a dual beside it. What does this support in 40:3?", "options": ["«شديد العقاب» lost its ال to match the words around it", "«شديد العقاب» is plural in meaning", "The و joins two mercies", "«التوب» is a plural of توبة"], "answer": "«شديد العقاب» lost its ال to match the words around it", "explanation": "al-Zamakhsharī uses it to show Arabs bend form for pairing (ازدواج); al-Ālūsī repeats the idea as مشاكلة."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:16', 'QR:SP:40:1-3', 16, 'focus', '40:2', 'Reasoned steps from the names', 'الاستدلال العقلي من الأسماء', 'al-Rāzī sets the āyāt out as numbered questions (مسائل) and reasons step by step: العزيز here means ''no like'' (since الله already shows power), what has no like is not a body, so He has no desire and no need; العليم is an intensive form that needs knowledge of every knowable.', '["razi"]', '{}', '["tafsir_sent:QRTA:razi:40-01:5-8", "tafsir_sent:QRTA:razi:40-01:22-24", "tafsir_sent:QRTA:razi:40-01:27-29", "tafsir_sent:QRTA:razi:40-01:30-31", "tafsir_sent:QRTA:razi:40-01:32-32"]', '{"prompt": "One reading says «العزيز» in 40:2 cannot mean ''powerful'' here. Why?", "options": ["The name الله already shows He is powerful, so العزيز must add ''He has no like''", "Power is already in «العليم»", "''Powerful'' would make the verse repeat «شديد العقاب»", "العزيز only means ''dear'' or ''rare''"], "answer": "The name الله already shows He is powerful, so العزيز must add ''He has no like''", "explanation": "al-Rāzī: each name should add something new, so العزيز = لا مثل له, which leads to ''not a body'' and ''free of need''."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:17', 'QR:SP:40:1-3', 17, 'focus', '40:1', 'Links between sūras and the حم group', 'المناسبة وفضل الحواميم', 'al-Ālūsī dwells on the place of the sūra: how al-Zumar''s end (two fates) leads to an opening of forgiveness as a call to faith, why the seven حم sūras stand together, and many reports on their merit.', '["alusi"]', '{}', '["tafsir_sent:QRTA:alusi:40-01:20-21", "tafsir_sent:QRTA:alusi:40-01:22-24", "tafsir_sent:QRTA:alusi:40-01:25-25", "tafsir_sent:QRTA:alusi:40-01:26-27", "tafsir_sent:QRTA:alusi:40-01:28-29", "tafsir_sent:QRTA:alusi:40-01:40-42"]', '{"prompt": "Sūrat al-Zumar ends by showing where the believer and the unbeliever end up. Why does it fit that the next sūra opens with «غافر الذنب وقابل التوب»?", "options": ["It is an open call to the unbeliever to believe and turn back", "It repeats the threat so the unbeliever loses hope", "It changes topic to rulings of prayer", "It proves the sūra came down in Medina"], "answer": "It is an open call to the unbeliever to believe and turn back", "explanation": "al-Ālūsī''s المناسبة: after both fates are shown, forgiveness is offered as an invitation."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:18', 'QR:SP:40:1-3', 18, 'focus', '40:1', 'Is «حواميم» good Arabic?', 'جمع حم: الحواميم وآل حم', 'al-Ālūsī also argues over the plural of حم — حواميم, حاميمات, آل حم or ذوات حم — and explains آل here as ''having'' (like ذو), a figure of speech (مجاز), not ''family''.', '["alusi"]', '{}', '["tafsir_sent:QRTA:alusi:40-01:56-58", "tafsir_sent:QRTA:alusi:40-01:61-63", "tafsir_sent:QRTA:alusi:40-01:67-69", "tafsir_sent:QRTA:alusi:40-01:70-72", "tafsir_sent:QRTA:alusi:40-01:73-74"]', '{"prompt": "In «آل حم» (''the حم sūras''), what does «آل» mean?", "options": ["''Having / those with'' — like ذو, a figure of speech", "''Family'', as in the Prophet''s family", "''Followers'' of the sūra", "A plural sign added to حم"], "answer": "''Having / those with'' — like ذو, a figure of speech", "explanation": "al-Ālūsī: آل is put before names that cannot be made dual or plural (like تأبط شرا); here it is مجاز, not الأهل."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:19', 'QR:SP:40:1-3', 19, 'focus', '40:2', 'Speaking to deniers without emphasis', 'تنزيل المنكر منزلة غير المنكر', 'Ibn ʿĀshūr asks who the statement is for: the polytheists who deny the Qurʾān came from God. Yet it comes with no emphasis words, treating the denier as a non-denier, because the proofs around him should end his denial.', '["ibn_ashur"]', '{}', '["tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:7-7", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:8-9"]', '{"prompt": "«تنزيل الكتاب من الله» is told to people who deny it, yet it has no emphasis (no إنّ, no لـ). Why, on one reading?", "options": ["The deniers are treated as non-deniers, since the proofs around them should end their denial", "The speaker did not know they denied it", "Emphasis is never used in the opening of a sūra", "The statement is meant for believers only"], "answer": "The deniers are treated as non-deniers, since the proofs around them should end their denial", "explanation": "Ibn ʿĀshūr: this goes against what the situation seems to need (خلاف مقتضى الظاهر) — تنزيل المنكر منزلة غير المنكر."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:20', 'QR:SP:40:1-3', 20, 'focus', '40:1-3', 'An opening that sums up the sūra', 'براعة الاستهلال', 'Ibn ʿĀshūr reads the whole opening as a fine start (براعة الاستهلال) that points to the sūra''s main aims and hints that the deniers'' pride will vanish as it did for stronger nations; the forgiveness names tell them the way back is still open.', '["ibn_ashur"]', '{}', '["tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:20-22", "tafsir_sent:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:52-54"]', '{"prompt": "On one reading, after «العزيز العليم» warns the deniers, the names «غافر الذنب، قابل التوب» strengthen the message. What do they add for the deniers?", "options": ["Fixing their sin of rejection is still in their hands, as past nations who repented were forgiven", "Their rejection can never be forgiven", "Only believers are meant by forgiveness", "Forgiveness comes without any repentance"], "answer": "Fixing their sin of rejection is still in their hands, as past nations who repented were forgiven", "explanation": "Ibn ʿĀshūr calls this ترشيح of the تعريض: the threat is paired with an open door, part of the opening''s براعة الاستهلال."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:21', 'QR:SP:40:1-3', 21, 'theology', '40:3', 'Forgiving major sins before repentance', 'العفو عن الكبيرة قبل التوبة', 'al-Rāzī (Ashʿarī) sets out a view that forgiveness only comes when earned — minor sins cancelled by greater good, major sins only by repentance — and argues against it: «غافر الذنب» must mean forgiving major sins before repentance, or it would repeat «قابل التوب», cover nothing, and bring no special praise. «ذي الطول» (leaving a deserved punishment) points the same way.', '["razi"]', '{}', '["tafsir_sent:QRTA:razi:40-01:44-45", "tafsir_sent:QRTA:razi:40-01:46-49", "tafsir_sent:QRTA:razi:40-01:50-50", "tafsir_sent:QRTA:razi:40-01:51-54", "tafsir_sent:QRTA:razi:40-01:55-56", "tafsir_sent:QRTA:razi:40-01:57-59", "tafsir_sent:QRTA:razi:40-01:60-62", "tafsir_sent:QRTA:razi:40-01:124-126"]', '{"prompt": "One reading argues: if «غافر الذنب» meant forgiving a major sin after repentance, it would just repeat «قابل التوب». What does it conclude «غافر الذنب» means?", "options": ["God may forgive major sins even before repentance", "God forgives only minor sins", "God forgives only after good deeds outweigh the sin", "God forgives only unbelievers who later believe"], "answer": "God may forgive major sins even before repentance", "explanation": "al-Rāzī''s Ashʿarī argument from no-repetition, from الغفران as ''covering'', and from the setting of praise. The ''outweigh'' option is the view he refutes."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:22', 'QR:SP:40:1-3', 22, 'theology', '40:3', 'Is accepting repentance a duty on God?', 'قبول التوبة تفضّل لا وجوب', 'al-Rāzī says his school holds that God accepts repentance as a favour (تفضل), while المعتزلة made it a duty on God. His proof: God names it as praise, and doing a mere duty earns little praise.', '["razi"]', '{}', '["tafsir_sent:QRTA:razi:40-01:71-74"]', '{"prompt": "Which reading makes God''s acceptance of repentance a favour rather than a duty on Him?", "options": ["Since it is named as praise, and a mere duty earns little praise, acceptance is a favour (تفضل)", "Since repentance erases sin, God must accept it (واجب)", "Since God promised, acceptance is a debt He owes", "Since repentance is a deed, its reward is earned by right"], "answer": "Since it is named as praise, and a mere duty earns little praise, acceptance is a favour (تفضل)", "explanation": "al-Rāzī (Ashʿarī) argues this against المعتزلة, who said accepting repentance is واجب on God."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:23', 'QR:SP:40:1-3', 23, 'theology', '40:2-3', 'God above body, change and wrong', 'التنزيه', 'al-Rāzī uses the names to rule out likening God to creation: ''no like'' means not a body and free of need; His attributes never come into being, so «شديد العقاب» is always true; His punishment is never ugly (قبيح); and he notes that أهل التشبيه used «إليه» as an end-point, which he answers elsewhere.', '["razi"]', '{}', '["tafsir_sent:QRTA:razi:40-01:30-31", "tafsir_sent:QRTA:razi:40-01:97-98", "tafsir_sent:QRTA:razi:40-01:120-121", "tafsir_sent:QRTA:razi:40-01:136-136"]', '{"prompt": "Why, on one reading, can «شديد العقاب» be a lasting description of God, not something that started at a time?", "options": ["God''s attributes do not come into being or renew, so it is always true of Him", "Because the punishment of the Fire has already begun", "Because ''severe'' is an intensive form", "Because it is a substitute, not a describing word"], "answer": "God''s attributes do not come into being or renew, so it is always true of Him", "explanation": "al-Rāzī: God''s attributes are free of الحدوث والتجدد — a kalām point he uses to solve the grammar problem."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:24', 'QR:SP:40:1-3', 24, 'theology', '40:3', 'Reward is a favour, not a debt', 'الثواب فضل لا دَين', 'al-Ālūsī takes الطول as reward and blessings too. Against the claim that a promised reward is a debt and so not a favour, he answers that making the promise was never a duty in the first place.', '["alusi"]', '{}', '["tafsir_sent:QRTA:alusi:40-01:112-113"]', '{"prompt": "Someone says: ''A reward God promised is like a debt, so it is not a favour.'' What answer fits the reading that الطول includes reward?", "options": ["Making the promise was not a duty, so the reward stays a favour", "A debt and a favour are the same thing", "Reward is earned by deeds, so it is never a favour", "الطول only means sparing punishment, never reward"], "answer": "Making the promise was not a duty, so the reward stays a favour", "explanation": "al-Ālūsī''s Sunni answer: nothing is owed by God at the start, so even promised reward is فضل."}');
INSERT OR REPLACE INTO qr_tafsir_contrast (id, passage_id, ord, kind, ayah, topic_en, topic_ar, point_en, books_json, positions_json, sentences_json, drill_json) VALUES ('QR:SP:40:1-3:25', 'QR:SP:40:1-3', 25, 'theology', '40:3', 'Is repentance surely accepted?', 'هل قبول التوبة مقطوع به؟', 'al-Ālūsī notes أهل السنة hold two views on whether God surely accepts a sinner''s repentance; another commentary reads the plain sense as sure acceptance, even of unbelief. He keeps the ''two mercies'' reading of the و because it works on the principles of both أهل السنة and المعتزلة.', '["alusi"]', '{}', '["tafsir_sent:QRTA:alusi:40-01:124-124", "tafsir_sent:QRTA:alusi:40-01:126-126", "tafsir_sent:QRTA:alusi:40-01:127-128"]', '{"prompt": "The ''two mercies'' reading of the و in «وقابل التوب» is kept by one commentator for a stated reason. What is it?", "options": ["It works on the basic beliefs of both Sunnis and Muʿtazilīs", "Only the Muʿtazilīs accept it", "It is the only reading with a report from the Prophet", "It proves God must accept every repentance"], "answer": "It works on the basic beliefs of both Sunnis and Muʿtazilīs", "explanation": "al-Ālūsī: a reading that fits both schools should not be dropped for weaker ones; he also notes Sunnis differ on whether acceptance is certain."}');
